insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('LI', 'default', 'Kontenrahmen nach Art. 1045 ff. PGR', '{}'::jsonb, true, 'companies', array['LI-PGR-BS', 'LI-PGR-IS']::text[], null, 'Das liechtensteinische Recht schreibt keinen gesetzlichen Kontenplan vor. Art. 1045 PGR verpflichtet zur ordnungsmässigen Rechnungslegung, Art. 1046 Abs. 1 PGR verlangt Geschäftsbücher, die einem sachverständigen Dritten einen Überblick über die Geschäftsvorfälle geben, Art. 1048 Abs. 2 PGR nennt Bilanz, Erfolgsrechnung und gegebenenfalls Anhang als Jahresrechnung, und Art. 1051 PGR gibt nur die Grobgliederung der Bilanz vor (Umlauf- und Anlagevermögen, Fremd- und Eigenkapital, Rechnungsabgrenzungsposten). Dieser Kontenrahmen ist ein Vorschlag, der dieser Grobgliederung folgt und im Übrigen die in der Praxis verbreitete schweizerische Vierstellerlogik teilt, weil die liechtensteinische Praxis auf dem Schweizer Franken und dem Schweizer Kontenrahmen KMU aufbaut; er kopiert diesen nicht — siehe README.md.', 'pgr')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

