insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('LI', 'LI-P-26', 'Einkauf Material-/Dienstleistungsaufwand, reduzierter Satz 2,6 %', '{}'::jsonb, null, 'percent', 2.6, 'purchase', 'domestic', date '2024-01-01', null, 'Art. 28 Abs. 1 Bst. a MWSTG, Ziffer 400 der Abrechnung, zum reduzierten Satz von Art. 25 Abs. 2 MWSTG.', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-P-81', 'Einkauf Material-/Dienstleistungsaufwand, Normalsatz 8,1 %', '{}'::jsonb, null, 'percent', 8.1, 'purchase', 'domestic', date '2024-01-01', null, 'Art. 28 Abs. 1 Bst. a MWSTG — Anspruch auf Abzug der in Rechnung gestellten Inlandsteuer im Rahmen der unternehmerischen Tätigkeit. Ziffer 400 der Abrechnung (Vorsteuer auf Material- und Dienstleistungsaufwand), getrennt von den Investitionen (Ziffer 405, siehe LI-P-81-INV). Eine Bemessungsgrundlage verlangt die Abrechnung für den Bezug nicht, weshalb dieser Code keine base-Buchung trägt.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-P-81-INV', 'Einkauf Investitionen und übriger Betriebsaufwand, Normalsatz 8,1 %', '{}'::jsonb, null, 'percent', 8.1, 'purchase', 'domestic', date '2024-01-01', null, 'Art. 28 Abs. 1 Bst. a MWSTG, ausgewiesen unter Ziffer 405 der Abrechnung (Vorsteuer auf Investitionen und übrigem Betriebsaufwand) — dieselbe Grundlage wie LI-P-81, aber die andere Zeile, weil die Abrechnung zwischen laufendem Aufwand und Investitionen unterscheidet.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-P-81-NA', 'Einkauf für eine von der Steuer ausgenommene Tätigkeit, Normalsatz 8,1 % (nicht abziehbar)', '{}'::jsonb, null, 'percent', 8.1, 'purchase', 'exempt', date '2024-01-01', null, 'Art. 29 Abs. 1 MWSTG — kein Anspruch auf Vorsteuerabzug bei Leistungen, die für die Erbringung von der Steuer ausgenommener Leistungen verwendet werden, für deren Versteuerung nicht optiert wurde. Die vom Lieferanten in Rechnung gestellte Steuer ist Teil der Anschaffungskosten und wird auf dem Konto der belasteten Zeile gebucht; die Abrechnung hat dafür keine eigene Ziffer.', null, null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-P-BEZUGSTEUER-81', 'Bezug einer Dienstleistung aus dem Ausland, Bezugsteuer 8,1 %', '{}'::jsonb, null, 'percent', 8.1, 'purchase', 'foreign_services_received', date '2024-01-01', null, 'Art. 45 Abs. 1 Bst. a und Abs. 2 MWSTG — der Bezugsteuer unterliegen Dienstleistungen mit Ort im Inland (Art. 8 Abs. 1), die von Unternehmen mit Sitz im Ausland erbracht werden, die nicht im Register der steuerpflichtigen Personen eingetragen sind; steuerpflichtig ist der Empfänger, wenn er nach Art. 10 steuerpflichtig ist oder im Kalenderjahr solche Leistungen für mehr als 10 000 Franken bezieht. Art. 46 verweist für Bemessung und Satz auf Art. 24 und 25; Art. 28 Abs. 1 Bst. b erlaubt den gleichzeitigen Abzug der deklarierten Bezugsteuer als Vorsteuer. Ziffer 383 weist die Bezugsteuer im Total der geschuldeten Steuer (Ziffer 399) aus, Ziffer 400 den Abzug. Ein inländisches Reverse-Charge-Verfahren kennt das Gesetz nicht.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-P-IMPORT-81', 'Einfuhr von Gegenständen, Einfuhrsteuer 8,1 %', '{}'::jsonb, null, 'percent', 8.1, 'purchase', 'import', date '2024-01-01', null, 'Art. 50 MWSTG — für die Steuer auf der Einfuhr von Gegenständen gelten die aufgrund des Vertrages vom 28. Oktober 1994 mit der Schweizerischen Eidgenossenschaft betreffend die Mehrwertsteuer im Fürstentum Liechtenstein massgeblichen schweizerischen Rechtsvorschriften; sie wird beim Bundesamt für Zoll und Grenzsicherheit (BAZG) entrichtet, ausser im Verlagerungsverfahren (Art. 51). Art. 28 Abs. 1 Bst. c MWSTG lässt die entrichtete Einfuhrsteuer als Vorsteuer abziehen (Ziffer 405). Dieser Code bildet nur den Vorsteuerabzug ab, keine Schuld gegenüber der Steuerverwaltung.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-S-26', 'Verkauf, reduzierter Satz 2,6 %', '{}'::jsonb, null, 'percent', 2.6, 'sale', 'domestic', date '2024-01-01', null, 'Art. 25 Abs. 2 MWSTG — der reduzierte Steuersatz von 2,6 % gilt für eine abschliessende Liste von Leistungen: Wasser in Leitungen, Lebensmittel nach dem schweizerischen Lebensmittelgesetz ohne alkoholische Getränke, Vieh, Geflügel, Fische, Getreide, Sämereien und Pflanzen, Futtermittel, Dünger, Medikamente, Zeitungen, Zeitschriften und Bücher ohne Reklamecharakter, Produkte für die Monatshygiene, u.a. Gastgewerbliche Leistungen unterliegen nach Abs. 3 dem Normalsatz. Fassung LGBl. 2023 Nr. 221.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-S-38-HEB', 'Beherbergungsleistung, Sondersatz 3,8 %', '{}'::jsonb, null, 'percent', 3.8, 'sale', 'domestic', date '2024-01-01', null, 'Art. 25 Abs. 4 MWSTG — die Steuer auf Beherbergungsleistungen (Unterkunft einschliesslich Frühstück, auch wenn dieses separat berechnet wird) beträgt 3,8 % (Sondersatz). Der gelesene liechtensteinische Gesetzestext nennt keine Befristung dieses Satzes; die schweizerische Befristung bis 31. Dezember 2027 steht nicht in ihm. Fassung LGBl. 2023 Nr. 221.', 'S', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-S-81', 'Verkauf, Normalsatz 8,1 %', '{}'::jsonb, null, 'percent', 8.1, 'sale', 'domestic', date '2024-01-01', null, 'Art. 25 Abs. 1 MWSTG — die Steuer beträgt 8,1 % (Normalsatz); die Abs. 2 und 4 bleiben vorbehalten. Der Wortlaut in der Fassung vom 1. Januar 2026 geht auf LGBl. 2023 Nr. 221 zurück; der Beginn am 1. Januar 2024 (zuvor 7,7 %) stammt aus Sekundärquellen und dem Gleichlauf mit dem schweizerischen Recht, nicht aus dem Landesgesetzblatt selbst.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-S-EXCLU', 'Von der Steuer ausgenommene Leistung (ohne Option)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2010-01-01', null, 'Art. 21 Abs. 1 und 2 MWSTG — eine von der Steuer ausgenommene Leistung ist nicht steuerbar, sofern nicht nach Art. 22 für ihre Versteuerung optiert wird; es besteht dafür kein Anspruch auf Vorsteuerabzug (Art. 29 Abs. 1). Beispiel in Art. 21 Abs. 2 Ziff. 21: die Überlassung von Grundstücken und Grundstücksteilen zum Gebrauch oder zur Nutzung. Kein exemption_code: Liechtenstein liegt ausserhalb des gemeinsamen Mehrwertsteuersystems der EU, dessen Liste VATEX Art. 21 MWSTG nicht kennt.', 'E', null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-S-EXPORT', 'Ausfuhrlieferung (von der Steuer befreit)', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2010-01-01', null, 'Art. 23 Abs. 1 und Abs. 2 Ziff. 1 MWSTG — die Lieferung von Gegenständen, die direkt ins Ausland befördert oder versendet werden, ist von der Steuer befreit; auf ihr ist keine Inlandsteuer geschuldet, und der Vorsteuerabzug bleibt erhalten (echte Befreiung, im Gegensatz zu Art. 21). «Inland» ist nach Art. 3 Bst. a MWSTG das Gebiet Liechtensteins sowie ausländische Gebiete gemäss staatsvertraglicher Vereinbarung; ob und welche Lieferungen in die Schweiz davon erfasst sind, ist in README.md vermerkt und von diesem Code nicht entschieden.', 'G', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null),
  ('LI', 'LI-S-FOREIGN', 'Dienstleistung mit Erbringungsort im Ausland', '{}'::jsonb, null, 'percent', 0, 'sale', 'not_subject', date '2010-01-01', null, 'Art. 8 Abs. 1 MWSTG — als Ort der Dienstleistung gilt der Ort, an dem der Empfänger den Sitz seiner wirtschaftlichen Tätigkeit oder eine Betriebsstätte hat (Empfängerortsprinzip); Art. 18 Abs. 1 MWSTG unterstellt der Inlandsteuer nur die im Inland erbrachten Leistungen. Eine Dienstleistung mit Ort im Ausland ist nicht steuerbar.', 'O', null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'mwstg', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
