insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('LI', 'LI-MWST-ABR', 'MWST-Abrechnung, effektive Methode (Nummerierung des Formulars Nr. 4470)', array['month', 'quarter', 'half_year', 'year']::declaration_period[], null, date '2024-01-01', null, 'Art. 35 Abs. 1 MWSTG — die Abrechnung erfolgt vierteljährlich, bei Anwendung der Saldosteuersätze (Art. 37 Abs. 1 und 2) halbjährlich. Art. 35 Abs. 1a MWSTG lässt auf Antrag eine monatliche Abrechnung bei regelmässigem Vorsteuerüberschuss (Bst. a) oder eine jährliche bei einem Umsatz von höchstens 5 005 000 Franken aus steuerbaren Leistungen (Bst. b) zu; Art. 35 Abs. 2 erlaubt der Steuerverwaltung in begründeten Fällen andere Perioden. Welche gilt, hängt von der gewählten Methode und vom Umsatz ab, weshalb dieser Pack keinen period_default setzt. Art. 58 Abs. 1 MWSTG: einzureichen innert 60 Tagen nach Ablauf der Abrechnungsperiode; Art. 76 Abs. 1: Zahlung ebenfalls innert 60 Tagen. Die Ziffern übernehmen die Nummerierung des schweizerischen Formulars Nr. 4470; das liechtensteinische Formular auf dem eMWST-Portal war nicht lesbar — siehe README.md.', true,null, null, null, null, null, null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('LI', 'LI-MWST-ABR', '200', 'base', 'Total der vereinbarten oder vereinnahmten Entgelte (Weltumsatz)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Ziffer 200 — Art. 18 Abs. 1 MWSTG (Total der vereinbarten oder vereinnahmten Entgelte); Nummerierung der Vorlage Formular Nr. 4470, das liechtensteinische Formular war nicht lesbar.', 'mwstg'),
  ('LI', 'LI-MWST-ABR', '205', 'base', 'Entgelte aus optierten, von der Steuer ausgenommenen Leistungen', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Ziffer 205 — Art. 22 MWSTG (Option) — von diesem Pack nicht gebucht, siehe README.md; Nummerierung der Vorlage Formular Nr. 4470, das liechtensteinische Formular war nicht lesbar.', 'mwstg'),
  ('LI', 'LI-MWST-ABR', '220', 'base', 'Von der Steuer befreite Leistungen (Ausfuhr, Art. 23)', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Ziffer 220 — Art. 23 MWSTG (von der Steuer befreite Leistungen); Nummerierung der Vorlage Formular Nr. 4470, das liechtensteinische Formular war nicht lesbar.', 'mwstg'),
