insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key, result_in_progress, result_in_progress_name, result_in_progress_name_i18n)
values
  ('LI-PGR-BS', 'LI', 'default', 'Bilanz nach Art. 1051 PGR', 'balance_sheet', 'LI-PGR', date '1970-01-01', null, 'PGR Art. 1048 Abs. 2 — die Jahresrechnung besteht aus Bilanz, Erfolgsrechnung und, falls erforderlich, einem Anhang. Art. 1051 Abs. 1 und 2 PGR: die Bilanz weist das Umlauf- und das Anlagevermögen, das Fremd- und das Eigenkapital sowie die Rechnungsabgrenzungsposten aus. Das PGR schreibt keine feinere Mindestgliederung vor; die Unterzeilen unten sind die Gliederung dieses Kontenrahmens, wie sie in der Praxis üblich ist (siehe README.md), keine Ziffern des Gesetzes.', 'pgr', 'combined', 'Ergebnis des laufenden Geschäftsjahres', '{}'::jsonb),
  ('LI-PGR-IS', 'LI', 'default', 'Erfolgsrechnung nach Art. 1048 PGR', 'income_statement', 'LI-PGR', date '1970-01-01', null, 'PGR Art. 1048 Abs. 2 und Art. 1051 Abs. 1 — die Erfolgsrechnung bringt das Verhältnis zwischen Aufwendungen und Erträgen zum Ausdruck. Das PGR gibt für sie keine Mindestgliederung vor; die Zeilen sind die Gliederung dieses Kontenrahmens (siehe README.md).', 'pgr', null, null, '{}'::jsonb)
