update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = 0,
  late_payment_reference        = '§ 904 ABGB: Ist die Zahlungsfrist nicht bestimmt, so tritt die Verbindlichkeit nach Mahnung ein. § 1333 Abs. 1 ABGB vergütet den durch die Verzögerung der Zahlung einer Geldforderung entstandenen Schaden durch die gesetzlichen Zinsen (§ 1000 Abs. 1 ABGB: fünf vom Hundert auf ein Jahr). Das ABGB kennt keine gesetzliche Zahlungsfrist von 30 Tagen und keine gesetzliche Pauschale für Beitreibungskosten (§ 1333 Abs. 3 ABGB lässt nur den Ersatz weiterer nachgewiesener Schäden zu). Für Steuerschulden gegenüber dem Land gilt dagegen Art. 77 MWSTG (Verzugszins ohne Mahnung); er ist nicht Gegenstand der Rechnung zwischen Unternehmen.',
  numbering_legal_reference     = 'Art. 26 Abs. 2 MWSTG nennt «in der Regel» sechs Angaben der Rechnung (Bst. a–f: Name und Ort des Leistungserbringers samt Registernummer, Name und Ort des Leistungsempfängers, Datum oder Zeitraum der Leistung, soweit er vom Rechnungsdatum abweicht, Art, Gegenstand und Umfang der Leistung, Entgelt, Steuersatz und Steuerbetrag) und verlangt keine fortlaufende Rechnungsnummer. Art. 1046 Abs. 1 PGR verlangt Geschäftsbücher, in denen sich die Geschäftsvorfälle in ihrer Entstehung und Abwicklung verfolgen lassen, schreibt aber kein Nummerierungsschema vor. Dieser Pack schlägt daher ein Format vor, ohne eine gesetzliche Lückenlosigkeit zu behaupten, die keine Norm verlangt.',
  numbering_source_key          = 'mwstg',
  payment_terms_legal_reference = '§ 904 ABGB — ist die Zahlungsfrist auf keine Art bestimmt, tritt die Verbindlichkeit nach Mahnung ein; § 1333 Abs. 1 ABGB regelt die Verzugszinsen. Der Pack setzt deshalb keine gesetzliche Zahlungsfrist (legal_payment_days 0).',
  payment_terms_source_key      = 'abgb',
  tax_point_rule                = 'invoice_date',
  tax_point_legal_reference     = 'Art. 39 Abs. 1 MWSTG — es wird nach vereinbarten Entgelten abgerechnet; Art. 40 Abs. 1 Bst. a MWSTG — die Umsatzsteuerschuld entsteht mit der Rechnungsstellung. Art. 39 Abs. 2 MWSTG lässt auf Antrag die Abrechnung nach vereinnahmten Entgelten zu; dieser unternehmensweite Methodenwechsel wird von diesem Pack nicht abgebildet — siehe README.md.',
  tax_point_source_key          = 'mwstg',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Am 23. Oktober 2026 verlangt weder das MWSTG (Art. 26 regelt nur den Inhalt einer Rechnung, nicht ihre Form) noch das PGR (Art. 1046 ff. regeln die Buchführung) den Austausch strukturierter elektronischer Rechnungen zwischen Unternehmen. Eine solche Pflicht wurde in den gelesenen Texten nicht gefunden; eine Mitteilung der Steuerverwaltung oder der Regierung dazu war nicht lesbar (llv.li antwortet Skripten mit 403), siehe README.md.',
  einvoice_source_key           = 'mwstg',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_account_scheme           = 'iban',
  bank_statement_formats        = array['camt.053', 'mt940', 'csv']::text[],
